import{_ as s,a0 as r,w as n,s as G,ao as o,I as l,x as i,a1 as e,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"Git 系列（五）：三個 Git 圖形化工具 | LCTT x X-CMD","titleTemplate":false,"description":"Git 系列（五）：三個 Git 圖形化工具 | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Git 系列（五）：三個 Git 圖形化工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Git 系列（五）：三個 Git 圖形化工具 | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160802 3 graphical tools for Git","title":"Git 系列（五）：三個 Git 圖形化工具","tag":"201608","desc":""},"relativePath":"201608/20160802 3 graphical tools for Git.md","filePath":"[post].md"}'),h={name:"201608/20160802 3 graphical tools for Git.md"};function d(g,t,u,S,f,m){const p=r("Link");return n(),G("div",null,[t[21]||(t[21]=o('<h1 id="git-系列-五-三個-git-圖形化工具" tabindex="-1">Git 系列（五）：三個 Git 圖形化工具 <a class="header-anchor" href="#git-系列-五-三個-git-圖形化工具" aria-label="Permalink to “Git 系列（五）：三個 Git 圖形化工具”">​</a></h1><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/government/BUSINESS_meritladder.png?itok=4CAH2wV0" alt=""></p><p>在本文裏，我們來了解幾個能幫你在日常工作中舒服地用上 Git 的工具。</p><p>我是在這許多漂亮界面出來之前學習的 Git，而且我的日常工作經常是基於字符界面的，所以 Git 本身自帶的大部分功能已經足夠我用了。在我看來，最好能理解 Git 的工作原理。不過，能有的選也不錯，下面這些就是能讓你不用終端就可以開始使用 Git 的一些方式。</p><h3 id="kde-dolphin-裏的-git" tabindex="-1">KDE Dolphin 裏的 Git <a class="header-anchor" href="#kde-dolphin-裏的-git" aria-label="Permalink to “KDE Dolphin 裏的 Git”">​</a></h3><p>我是一個 KDE 用户，如果不在 Plasma 桌面環境下，就是在 Fluxbox 的應用層。Dolphin 是一個非常優秀的文件管理器，有很多配置項以及大量秘密小功能。大家為它開發的插件都特別好用，其中一個幾乎就是完整的 Git 界面。是的，你可以直接在自己的桌面上很方便地管理你的 Git 倉庫。</p><p>但首先，你得先確認已經安裝了這個插件。有些發行版帶的 KDE 將各種插件都裝的滿滿的，而有些只裝了一些最基本的，所以如果你在下面的步驟裏沒有看到 Git 相關選項，就在你的軟件倉庫裏找找類似 dolphin-extras 或者 dolphin-plugins 的包。</p><p>要打開 Git 集成功能，在 Dolphin 的任一窗口裏點擊 Settings 菜單，並選擇 Configure Dolphin。</p><p>在彈出的 Configure Dolphin 窗口裏，點擊左邊側欄裏的 Services 圖標。</p><p>在 Services 面板裏，滾動可用的插件列表找到 Git。</p><p><img src="https://opensource.com/sites/default/files/4_dolphinconfig.jpg" alt=""></p><p>（勾選上它，）然後保存你的改動並關閉 Dolphin 窗口。重新啓動 Dolphin，瀏覽一個 Git 倉庫試試看。你會發現現在所有文件圖標都帶有標記：綠色方框表示已經提交的文件，綠色實心方塊表示文件有改動，沒加入庫裏的文件沒有標記，等等。</p><p>之後你在 Git 倉庫目錄下點擊鼠標右鍵彈出的菜單裏就會有 Git 選項了。你在 Dolphin 窗口裏點擊鼠標就可以檢出一個版本，推送或提交改動，還可以對文件進行 <code>git add</code> 或 <code>git remove</code> 操作。</p><p><img src="https://opensource.com/sites/default/files/4_dolphingit.jpg" alt=""></p><p>不過 Dolphin 不支持克隆倉庫或是改變遠端倉庫路徑，需要到終端窗口操作，按下 F4 就可以很方便地進行切換。</p><p>坦白地説，KDE 的這個功能太牛了，這篇文章已經可以到此為止。將 Git 集成到原生文件管理器裏可以讓 Git 操作非常清晰；不管你在工作流程的哪個階段，一切都能直接地擺在面前。在終端裏 Git，切換到 GUI 後也是一樣 Git。完美。</p><p>不過別急，還有好多呢！</p><h3 id="sparkleshare" tabindex="-1">Sparkleshare <a class="header-anchor" href="#sparkleshare" aria-label="Permalink to “Sparkleshare”">​</a></h3><p>SparkleShare 來自桌面環境的另一大陣營，由一些 GNOME 開發人員發起，一個使用文件同步模型 (“就像 Dropbox 一樣!”) 的項目。不過它並沒有集成任何 GNOME 特有的組件，所以你可以在任何平台使用。</p><p>如果你在用 Linux，可以從你的軟件倉庫直接安裝 SparkleShare。如果是其它操作系統，可以去 SparkleShare 網站下載。你可以不用看 SparkleShare 網站上的指引，那個是告訴你如何架設 SparkleShare 服務器的，不是我們這裏討論的。當然你想的話也可以架設 SparkleShare 服務器，但是 SparkleShare 能兼容 Git 倉庫，所以其實沒必要再架一個自己的。</p><p>在安裝完成後，從應用程序菜單裏啓動 SparkleShare。走一遍設置嚮導，只有兩個步驟外加一個簡單介紹，然後可以選擇是否將 SparkleShare 設置為隨桌面自動啓動。</p><p><img src="https://opensource.com/sites/default/files/4_sparklesetup.jpg" alt=""></p><p>之後在你的系統托盤裏會出現一個橙色的 SparkleShare 目錄。目前，SparkleShare 對你電腦上的任何東西都一無所知，所以你需要添加一個項目。</p><p>要添加一個目錄給 SparkleShare 追蹤，可以點擊系統托盤裏的 SparkleShare 圖標然後選擇 Add Hosted Project。</p><p><img src="https://opensource.com/sites/default/files/4_sparklehost.jpg" alt=""></p><p>SparkleShare 支持本地 Git 項目，也可以是存放在像 GitHub 和 Bitbucket 這樣的公共 Git 服務器上的項目。要獲得完整訪問權限，你可能會需要使用 SparkleShare 生成的客户端 ID。這是一個 SSH 密鑰，作為你所用到服務的授權令牌，包括你自己的 Git 服務器，應該也使用 SSH 公鑰認證而不是用户名密碼。將客户端 ID 拷貝到你服務器上 Git 用户的 <code>authorized_hosts</code> 文件裏，或者是你的 Git 主機的 SSH 密鑰面板裏。</p><p>在配置要你要用的主機後，SparkleShare 會下載整個 Git 項目，包括（你可以自己選擇）提交歷史。可以在 ~/SparkleShare 目錄下找到同步完成的文件。</p><p>不像 Dolphin 那樣的集成方式，SparkleShare 是不透明的，讓人心裏沒底。在你做出改動後，它會悄悄地把改動同步到服務器遠端項目中。對大部分人來説，這樣做有一個很大的好處：可以用到 Git 的全部威力但是不用維護。對我來説，這樣有些亂，因為我想自己管理我的提交以及要用的分支。</p><p>SparkleShare 可能不適合所有人，但是它是一個強大而且簡單的 Git 解決方案，展示了不同的開源項目完美地協調整合到一起後所創造出的獨特項目。</p><h3 id="git-cola" tabindex="-1">Git-cola <a class="header-anchor" href="#git-cola" aria-label="Permalink to “Git-cola”">​</a></h3><p>另一種配合 Git 倉庫工作的模型，沒那麼原生，更多的是監視方式；不是使用一個集成的應用程序和你的 Git 項目直接交互，而是你可以使用一個桌面客户端來監視項目改動，並隨意處理每一個改動。這種方式的一個優勢就是專注。當你實際只用到項目裏的三個文件的時候，你可能不會關心所有的 125 個文件，能將這三個文件挑出來就很方便了。</p>',31)),l("p",null,[t[2]||(t[2]=i("如果你覺得有好多 Git 託管網站，那只是你還不知道 Git 客户端有多少。",-1)),e(p,{href:"https://git-scm.com/downloads/guis"},{default:a(()=>[...t[0]||(t[0]=[i("桌面上的 Git 客户端",-1)])]),_:1}),t[3]||(t[3]=i(" 上有一大把。實際上，Git 默認自帶一個圖形客户端。它們中最跨平台、最可配置的就是開源的 ",-1)),e(p,{href:"https://git-cola.github.io/"},{default:a(()=>[...t[1]||(t[1]=[i("Git-cola",-1)])]),_:1}),t[4]||(t[4]=i(" 客户端，用 Python 和 Qt 寫的。",-1))]),l("p",null,[t[6]||(t[6]=i("如果你在用 Linux，Git-cola 應該在你的軟件倉庫裏就有。不是的話，可以直接從它的",-1)),e(p,{href:"https://git-cola.github.io/"},{default:a(()=>[...t[5]||(t[5]=[i("網站下載",-1)])]),_:1}),t[7]||(t[7]=i("並安裝：",-1))]),t[22]||(t[22]=o('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python setup.py install</span></span></code></pre></div><p>啓動 git-cola 後，會有三個按鈕用來打開倉庫，創建新倉庫，或克隆倉庫。</p><p>不管選哪個，最終都會停在一個 Git 倉庫中。和大多數我用過的客户端一樣，Git-cola 不會嘗試成為你的倉庫的接口；它們一般會讓操作系統工具來做這個。換句話説，我可以通過 Git-cola 創建一個倉庫，但隨後我就在 Thunar 或 Emacs 裏打開倉庫開始工作。打開 Git-cola 來監視倉庫很不錯，因為當你創建新文件，或者改動文件的時候，它們都會出現在 Git-cola 的狀態面板裏。</p><p>Git-cola 的默認佈局不是線性的。我喜歡從左向右分佈，因為 Git-cola 是高度可配置的，所以你可以隨便修改佈局。我自己設置成最左邊是狀態面板，顯示當前分支的任何改動，然後右邊是差異面板，可以瀏覽當前改動，然後是動作面板，放一些常用任務的快速按鈕，最後，最右邊是提交面板，可以寫提交信息。</p><p><img src="https://opensource.com/sites/default/files/4_gitcola.jpg" alt=""></p><p>不管怎麼改佈局，下面是 Git-cola 的通用流程：</p><p>改動會出現在狀態面板裏。右鍵點擊一個改動或選中一個文件，然後在動作面板裏點擊 Stage 按鈕來將文件加入待提交暫存區。</p><p>待提交文件的圖標會變成綠色三角形，表示該文件有改動並且正等待提交。你也可以右鍵點擊並選擇 Unstage Selected 將改動移出待提交暫存區，或者點擊動作面板裏的 Unstage 按鈕。</p><p>在差異面板裏檢查你的改動。</p><p>當準備好提交後，輸入提交信息並點擊 Commit 按鈕。</p><p>在動作面板裏還有其它按鈕用來處理其它普通任務，比如拉取或推送。菜單裏有更多的任務列表，比如用於操作分支，改動審查，變基等等的專用操作。</p><p>我更願意將 Git-cola 當作文件管理器的一個浮動面板（在不能用 Dolphin 的時候我只用 Git-cola）。雖然它的交互性沒有完全集成 Git 的文件管理器那麼強，但另一方面，它幾乎提供了原始 Git 命令的所有功能，所以它實際上更為強大。</p><p>有很多 Git 圖形客户端。有些是不提供源代碼的付費軟件，有些只是用來查看，有些嘗試加入新的特定術語（用 &quot;sync&quot; 替代 &quot;push&quot; ...?) 來重造 Git，也有一些只適合特定的平台。Git-cola 一直是能在任意平台上使用的最簡單的客户端，也是最貼近純粹 Git 命令的，可以讓用户在使用過程中學習 Git，即便是高手也會很滿意它的界面和術語。</p><h3 id="git-命令還是圖形界面" tabindex="-1">Git 命令還是圖形界面？ <a class="header-anchor" href="#git-命令還是圖形界面" aria-label="Permalink to “Git 命令還是圖形界面？”">​</a></h3><p>我一般不用圖形工具來操作 Git；一般我使用上面介紹的工具時，只是幫助其他人找出適合他們的界面。不過，最終歸結於怎麼適合你的工作。我喜歡基於終端的 Git 命令是因為它可以很好地集成到 Emacs 裏，但如果某天我幾乎都在用 Inkscape 工作時，我一般會很自然地使用 Dolphin 裏帶的 Git，因為我在 Dolphin 環境裏。</p><p>如何使用 Git 你自己可以選擇；但要記住 Git 是一種讓生活更輕鬆的方式，也是讓你在工作中更安全地嘗試一些瘋狂點子的方法。熟悉 Git 的工作模式，然後不管以什麼方式使用 Git，只要能讓你覺得最適合就可以。</p><p>在下一期文章裏，我們將瞭解如何架設和管理 Git 服務器，包括用户權限和管理，以及運行定製腳本。</p><hr>',18)),l("p",null,[t[9]||(t[9]=i("via: ",-1)),e(p,{href:"https://opensource.com/life/16/8/graphical-tools-git"},{default:a(()=>[...t[8]||(t[8]=[i("https://opensource.com/life/16/8/graphical-tools-git",-1)])]),_:1})]),l("p",null,[t[13]||(t[13]=i("作者：",-1)),e(p,{href:"https://opensource.com/users/seth"},{default:a(()=>[...t[10]||(t[10]=[i("Seth Kenlon",-1)])]),_:1}),t[14]||(t[14]=i(" 譯者：",-1)),e(p,{href:"https://github.com/zpl1025"},{default:a(()=>[...t[11]||(t[11]=[i("zpl1025",-1)])]),_:1}),t[15]||(t[15]=i(" 校對：",-1)),e(p,{href:"https://github.com/wxy"},{default:a(()=>[...t[12]||(t[12]=[i("wxy",-1)])]),_:1})]),l("p",null,[t[18]||(t[18]=i("本文由 ",-1)),e(p,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[16]||(t[16]=[i("LCTT",-1)])]),_:1}),t[19]||(t[19]=i(" 原創編譯，",-1)),e(p,{href:"https://linux.cn/"},{default:a(()=>[...t[17]||(t[17]=[i("Linux中國",-1)])]),_:1}),t[20]||(t[20]=i(" 榮譽推出",-1))])])}const b=s(h,[["render",d]]);export{D as __pageData,b as default};
